function cartPage(){let total=state.cart.reduce((s,x)=>s+x.price*x.qty,0),count=state.cart.reduce((s,x)=>s+x.qty,0);return `<main class="bagpage"><section class="bagcol"><h1>Shopping bag</h1><div class="shipping"><div>🚚 <b>Delivery to ${state.zip||'95054'}</b><br>🟢 Starting at $39.00<br>or $29.00 with IKEA Family</div><div>▣ <b>Pick up at IKEA East Palo Alto, CA</b><br>🟢 $2.00 or Free with IKEA Family</div><div>⌂ <b>Collect at CRST/N...</b><br>🟢 $14.00</div></div>${state.cart.map((x,i)=>{let p=item(x.id)||{name:'STUBBARP',description:'Leg, white stained oak effect, 2 pack/pack',image:'/assets/media-188.jpg'};let combo=x.id==='29209829'||x.id==='29612189';return `<div class="bagitem"><img src="${asset(p.image)}"><div class="iteminfo"><b>${p.name}</b><br>${p.description}<br><b class="blue">${combo?'17% off, save $43.00':'20% off, save $2.00'} with IKEA Family</b><p>🟢 Available for delivery<br>🟢 Available for Click & collect<br>🟢 Available for Collect near you</p>${combo?`<a onclick="openDrawer('parts')">Show included parts</a>`:''}<div class="itembottom"><a>Save for later</a><button onclick="removeItem(${i})">♜</button><div class="qty"><button onclick="quantity(${i},-1)">−</button>${x.qty}<button onclick="quantity(${i},1)">＋</button></div></div>${combo?`<div class="service">⚒　Assembly by Taskrabbit for BESTÅ　 <b>$${(58.5*x.qty).toFixed(2)}</b><input type="checkbox" onchange="state.assembly['${x.id}']=this.checked;save()"></div>`:`<div class="service">⚒　Assembly by Taskrabbit　$2.60* <input type="checkbox"></div>`}</div><b>$${(x.price*x.qty).toFixed(2)}</b></div>`}).join('')}</section><aside class="summary"><h3>Order summary</h3><div class="sumline">Products <b>${money(total)}</b></div><p>Shipping costs are calculated at checkout</p><hr><div class="sumline"><b>Total excluding tax</b><b>${money(total)}</b></div><p>▣ Afterpay<br>4 interest-free payments of ${money(total/4)} + tax</p><p><b>Save $${Math.round(state.cart.reduce((s,x)=>s+((x.id==='29209829'||x.id==='29612189'