function quantity(i,n){state.cart[i].qty=Math.max(1,state.cart[i].qty+n);save();render()}function removeItem(i){state.undo=state.cart.splice(i,1)[0];state.undo.name=item(state.undo.id)?.name||'STUBBARP';save();render()}function undo(){state.cart.push(state.undo);state.undo=null;save();render()}function addCart(id){let p=item(id);if(!p)return;let found=state.cart.find(x=>x.id===id);if(found)found.qty+=id==='20293568'?state.qty:1;else state.cart.push({id,qty:id==='20293568'?state.qty:1,price:p.regular_price||10});state.drawer='added';save();render()}function changeVariant(id){state.gallery=0;go(productUrl(id))}function toggleCompare(id){state.compare.includes(id)?state.compare=state.compare.filter(x=>x!==id):state.compare.length<5&&state.compare.push(id);save();render()}function toggleFilter(f){state.openFilter=state.openFilter===f?'':f;render()}function searchGo(q){if(q)state.query=q;state.menu='';go('/search/?q='+encodeURIComponent(state.query||'besta'))}function suggest(v){state.query=v;let old=$('#suggestions');if(old)old.remove();if(v){let el=document.createElement('div');el.id='suggestions';el.style='position:fixed;z-index:10;top:120px;left:48%;background:white;padding:24px;box-shadow:0 4px 20px #aaa;width:400px';el.innerHTML=`<b>Search suggestions</b><p onclick="searchGo('${v}')">⌕　${v}</p><p onclick="searchGo('besta')">BESTÅ storage system</p>`;document.body.append(el)}}function menu(x){state.menu=state.menu?null:x;render()}function openDrawer(x){state.drawer=x;render()}function closeDrawer(){state.drawer='';render()}function openModal(x){state.modal=x;render()}function modalHtml(){if(state.modal==='gallery'||state.modal==='dimensions'){let p=current(),gal=p.gallery||[p.image,'/assets/media-312.jpg','/assets/media-317.jpg'];return `<div class="modalbg" onclick="state.modal='';render()"><div class="modal" onclick="event.stopPropagation()"><button class="close" onclick="state.modal='';render()">×</button><div class="modalhead"><b onclick="state.modal='gallery';render()">All media</b><b>Video</b><b onclick="state.modal='dimensions';render()">Measurement</b></div>${state.modal==='dimensions'?`<img src="/assets/media-317.jpg"><h2>Measurements</h2><p>Width 47 1/4 "　Depth 16 1/2 "　Height 29 1/8 "</p>`:`<div class="cards">${gal.map(x=>`<img style="width:100%" src="${x}">`).join('')}</div>`}</div></div>`}if(state.modal==='reviews')return `<div class="modalbg" onclick="state.modal='';render()"><div class="modal reviewmodal" onclick="event.stopPropagation()"><button class="close" onclick="state.modal='';render()">×</button><div class="reviewlayout"><aside><h1 style="font-size:55px">3.7</h1>★★★★★<p>Based on 123 reviews</p><hr>${[5,4,3,2,1].map((n,i)=>`<p>${n} ★　<span style="display:inline-block;background:#ddd;width:140px;height:8px"><i style="display:block;background:#0058a3;height:8px;width:${70-i*11}%"></i></span>　${[54,30,10,12,17][i]}</p>`).join('')}<button class="pill wide">Write a review</button></aside><section><h1>Customer reviews</h1><button class="pill">☷ Filter</button> <button class="pill" onclick="state.sortOpen=!state.sortOpen;render()">☷ Sort by</button>${state.sortOpen?`<div class="service">${['Most recent','Oldest','Highest rated','Lowest rated','Most helpful'].map(x=>`<p><label><input type="radio" name="reviewSort" ${x==='Lowest rated'?'checked':''} onchange="state.reviewSort='${x}'">${x}</label></p>`).join('')}</div>`:''}<p>United States　　 Other countries</p><div class="service"><b>Reviews summary</b><p>BESTÅ offers a stylish design that enhances many spaces. Customers often report issues with overall stability and quality. They mention wobbly structures and difficulty aligning or securing doors.</p></div><p>Topics　 <button class="pill">Show all</button> <button class="pill">Quality (11)</button> <button class="pill">Assembly (11)</button> <button class="pill">Stability</button></p>${(state.reviewSort==='Lowest rated'?['So disappointed. Wobbly junk.','Looks good, functions bad']:['Looks good, functions bad','So disappointed. Wobbly junk.']).map((x,i)=>`<div class="reviewline"><b>${i?'★☆☆☆☆':'★★☆☆☆'}　　${i?'11/14/2024':'09/17/2026'}</b><h3>${x}</h3><p>The flimsy wood for the frame and plastic cam locks seriously degrade the quality of the overall product. The doors very easily misalign if the cabinet is nudged in any way.</p><p>Anonymous reviewer <span style="float:right">Helpful? (1)</span></p></div>`).join('')}</section></div></div></div>`;return ''}
