/^\d{5}$/.test(v)){ $('#zipError').textContent='Please enter a valid ZIP code.';return}state.zip=v;state.drawer='';save();render()}function selectStore(s){state.store=s;state.drawer='';save();render()}function filterStores(v){document.querySelectorAll('.store').forEach(x=>x.style.display=x.textContent.toLowerCase().includes(v.toLowerCase())?'':'none')}
function render(){if(!data)return;let t=type(),p=current();let html=header()+(t==='home'?home():t==='search'?listing():t==='product'?productPage(p):t==='compare'?comparison():cartPage());if(state.cookie&&t==='home')html+=`<div class="cookie"><p>IKEA US and our digital partners use cookies on this site. Some are strictly necessary to run the site and others are used for measuring site usage, enabling personalization and for advertising, marketing, and social media. View our <u>Privacy Policy</u>, <u>California Notice at Collection</u>, and <u>Cookie Policy</u> for more information.</p><button class="blackbtn">Your privacy choices</button><button class="blackbtn" onclick="state.cookie=false;localStorage.setItem('cookie','yes');render()">Ok</button></div>`;html+=drawerHtml()+modalHtml();$('#app').innerHTML=html;save()}","path":"app.js"},{"content":"# Local IKEA BESTÅ shopping journey

